        </div>
      )}
      {gpu && view === 'globe' ? <Globe gpu={gpu} points={points} height={height} focus={focus ?? { index: -1, nonce: 0 }} rowsFly={!!focus} /> : <MapView points={points} height={height} />}
    </div>
  )
}
